A.c26rimp=function(){X.xmodal('Import URL redirects','<p>Download a <a class="s23lnk" data-x="c26rtpl">sample CSV template</a> to see an example of the format required.</p><label class="c26dz" for="c26rf2"><span class="btn">Add files</span><span class="s23mut">Accepts .csv, .txt, and .xls</span><input type="file" id="c26rf2" accept=".csv,.txt,.xls" hidden></label><p id="c26rfn" class="s23mut"></p>','Upload file',function(){var f=q('#c26rf2').files[0];if(!f){X.xerr('Add a file first');return false}var r=new FileReader();r.onload=function(){var lines=String(r.result).split(/\r?\n/).filter(Boolean),n=0,skip=0;lines.forEach(function(l,i){var c=l.split(/[,\t]/).map(function(x){return x.replace(/^"|"$/g,'').trim()});if(i===0&&/redirect/i.test(c[0]))return;var fr=normPath(c[0]),to=c[1]?(/^https?:\/\//.test(c[1])?c[1]:normPath(c[1])):'';if(!fr||!to||reds().some(function(x){return x.from===fr})){skip++;return}reds().push({from:fr,to:to,at:Date.now()});n++});sv();toast(n+' redirects imported'+(skip?', '+skip+' skipped':''));location.hash='url-redirects';route()};r.readAsText(f)})};
